import json,sys
try:
    nb=json.load(open('/workspace/paper_analysis_RQ3.ipynb'))
except Exception as e:
    sys.exit(1)
out=[]
for cell in nb.get('cells',[]):
    if cell.get('cell_type')=='markdown':
        out.append(''.join(cell.get('source',[])))
    elif cell.get('cell_type')=='code':
        # collect textual outputs
        for o in cell.get('outputs',[]):
            if 'text' in o:
                t=o['text']
                out.append(''.join(t) if isinstance(t,list) else str(t))
            elif 'data' in o:
                tp=o['data'].get('text/plain') or o['data'].get('text') 
                if tp:
                    out.append(''.join(tp) if isinstance(tp,list) else str(tp))
# limit size to avoid extremely large outputs
content='\\n\\n'.join(out)[:200000]
open('/workspace/repro.txt','w').write(content)
PY
&& artisan format --expected /workspace/expected.md --repro /workspace/repro.txt) 
</mini_swe_agent_bash>

